import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:querypic/services/clip_tokenizer.dart';

/// Tokenizer goldens: expected ids generated by an independent Python
/// reference over the same vocab.json + merges.txt (tools-adjacent script).
/// Any Dart/Python divergence fails here, never silently on device.
ClipTokenizer _load() {
  final vocabJson = json.decode(
    File('sandbox/models/vocab.json').readAsStringSync(),
  ) as Map<String, dynamic>;
  final merges = File('sandbox/models/merges.txt').readAsStringSync();
  return ClipTokenizer.fromMaps(vocabJson, merges);
}

void main() {
  late ClipTokenizer tok;
  setUpAll(() => tok = _load());

  test('vocab pair parses (49408 tokens, ranked merges)', () {
    expect(tok.vocab.length, 49408);
    expect(tok.ranks, isNotEmpty);
    expect(tok.vocab['<|startoftext|>'], ClipTokenizer.sotId);
    expect(tok.vocab['<|endoftext|>'], ClipTokenizer.eotId);
  });

  test('output is always 77 ids: sot … eot, eot-padded', () {
    for (final q in ['sunset', 'a', '']) {
      final ids = tok.encode(q);
      expect(ids.length, ClipTokenizer.contextLength);
      expect(ids.first, ClipTokenizer.sotId);
      expect(ids[1], isNot(ClipTokenizer.sotId));
      expect(ids.contains(ClipTokenizer.eotId), isTrue);
      expect(ids.last, ClipTokenizer.padId);
    }
  });

  test('eotPosition finds the true end (first EOT at index>=1)', () {
    // 'a' -> [sot, a, eot, eot, ...]: position 2, not the padding.
    expect(ClipTokenizer.eotPosition(tok.encode('a')), 2);
    final sunset = tok.encode('sunset over the ocean');
    final eot = ClipTokenizer.eotPosition(sunset);
    expect(sunset[eot], ClipTokenizer.eotId);
    expect(sunset[eot - 1], isNot(ClipTokenizer.eotId));
    expect(ClipTokenizer.eotPosition(List.filled(77, 1)), 76);
  });

  test('goldens match the Python reference', () {
    expect(
      tok.encode('sunset').sublist(0, 4),
      [49406, 3424, 49407, 49407],
    );
    expect(
      tok.encode('receipt from home depot').sublist(0, 6),
      [49406, 30479, 633, 1137, 12589, 49407],
    );
    expect(
      tok.encode('happy birthday').sublist(0, 4),
      [49406, 900, 1166, 49407],
    );
    expect(
      tok.encode('beach sunset from last summer').sublist(0, 7),
      [49406, 2117, 3424, 633, 952, 1673, 49407],
    );
    expect(tok.encode('a').sublist(0, 3), [49406, 320, 49407]);
    expect(
      tok.encode('passport scan document').sublist(0, 5),
      [49406, 14739, 11261, 15121, 49407],
    );
  });

  test('casing is folded, gibberish still encodes', () {
    expect(
      tok.encode('Hello WORLD').sublist(0, 4),
      [49406, 3306, 1002, 49407],
    );
    final gib = tok.encode('zxqvkw');
    expect(gib.length, ClipTokenizer.contextLength);
    expect(gib.first, ClipTokenizer.sotId);
    for (final id in gib) {
      expect(id, inInclusiveRange(0, 49407));
    }
  });
}
